INSERT INTO governance_reserved_matters (matter_code,category,matter_title,approval_authority,decision_standard,secondary_approval,notes) SELECT 'RM-001','Corporate Structure','Alteration of company constitutional documents','Shareholders / Board as legally applicable','Formal corporate approval and applicable statutory filings','Company Secretary / Legal','Includes amendments to the Memorandum and Articles where legally permitted.' WHERE NOT EXISTS (SELECT 1 FROM governance_reserved_matters WHERE matter_code='RM-001');
INSERT INTO governance_reserved_matters (matter_code,category,matter_title,approval_authority,decision_standard,secondary_approval,notes) SELECT 'RM-002','Capital','Issue, allotment, transfer or material alteration of shares','Board / Shareholders as legally applicable','Formal approval, statutory compliance and corporate records update','Company Secretary / Legal','No employee or executive delegation overrides shareholder or board rights.' WHERE NOT EXISTS (SELECT 1 FROM governance_reserved_matters WHERE matter_code='RM-002');
INSERT INTO governance_reserved_matters (matter_code,category,matter_title,approval_authority,decision_standard,secondary_approval,notes) SELECT 'RM-003','Finance','Material borrowing, guarantees or security over company assets','Board / Shareholders as legally applicable','Approved financing terms, risk assessment and legal review','Finance + Legal','Thresholds should be set by board policy before execution.' WHERE NOT EXISTS (SELECT 1 FROM governance_reserved_matters WHERE matter_code='RM-003');
INSERT INTO governance_reserved_matters (matter_code,category,matter_title,approval_authority,decision_standard,secondary_approval,notes) SELECT 'RM-004','Assets','Acquisition or disposal of material company assets','Board / authorised executive within approved policy','Independent valuation or documented commercial rationale where appropriate','Finance + Legal','Delegated purchasing limits remain subject to this reserved-matters framework.' WHERE NOT EXISTS (SELECT 1 FROM governance_reserved_matters WHERE matter_code='RM-004');
INSERT INTO governance_reserved_matters (matter_code,category,matter_title,approval_authority,decision_standard,secondary_approval,notes) SELECT 'RM-005','Strategy','Entry into a materially new business line or regulated activity','Board / Shareholders as legally applicable','Strategic case, regulatory assessment and risk review','Legal / Compliance','Especially important for activities requiring licences or special regulatory treatment.' WHERE NOT EXISTS (SELECT 1 FROM governance_reserved_matters WHERE matter_code='RM-005');
INSERT INTO governance_reserved_matters (matter_code,category,matter_title,approval_authority,decision_standard,secondary_approval,notes) SELECT 'RM-006','Transactions','Merger, acquisition, disposal of a material business or restructuring','Board / Shareholders as legally applicable','Due diligence, valuation, legal review and formal resolution','Finance + Legal','Materiality should be defined by board policy.' WHERE NOT EXISTS (SELECT 1 FROM governance_reserved_matters WHERE matter_code='RM-006');
INSERT INTO governance_reserved_matters (matter_code,category,matter_title,approval_authority,decision_standard,secondary_approval,notes) SELECT 'RM-007','People','Appointment or removal of directors and key control officers','Shareholders / Board as legally applicable','Documented appointment/removal process and statutory compliance','Company Secretary / Legal','Operational hiring remains delegated through the workforce framework.' WHERE NOT EXISTS (SELECT 1 FROM governance_reserved_matters WHERE matter_code='RM-007');
INSERT INTO governance_reserved_matters (matter_code,category,matter_title,approval_authority,decision_standard,secondary_approval,notes) SELECT 'RM-008','Risk','Material litigation settlement or admission of liability','Board / authorised executive within approved policy','Legal risk assessment and documented settlement rationale','Legal','Emergency authority must be documented and reported.' WHERE NOT EXISTS (SELECT 1 FROM governance_reserved_matters WHERE matter_code='RM-008');
INSERT INTO governance_reserved_matters (matter_code,category,matter_title,approval_authority,decision_standard,secondary_approval,notes) SELECT 'RM-009','Technology & Data','Material change to critical systems, security posture or data governance','Board / Executive management within approved policy','Security, continuity, privacy and financial impact assessment','Technology + Legal / Compliance','Applies to systems classified as critical by company policy.' WHERE NOT EXISTS (SELECT 1 FROM governance_reserved_matters WHERE matter_code='RM-009');
INSERT INTO governance_reserved_matters (matter_code,category,matter_title,approval_authority,decision_standard,secondary_approval,notes) SELECT 'RM-010','Governance','Approval of annual strategy, budget and corporate risk appetite','Board / Shareholders as applicable','Formal review and documented approval','Finance + Executive Management','Operational budgets may subsequently be delegated within approved limits.' WHERE NOT EXISTS (SELECT 1 FROM governance_reserved_matters WHERE matter_code='RM-010');