CREATE TABLE IF NOT EXISTS governance_reserved_matters (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), matter_code text UNIQUE NOT NULL, category text NOT NULL, matter_title text NOT NULL, approval_authority text NOT NULL, decision_standard text NOT NULL, secondary_approval text, notes text, status text NOT NULL DEFAULT 'Active', created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now());
CREATE INDEX IF NOT EXISTS governance_reserved_matters_category_idx ON governance_reserved_matters(category);
CREATE INDEX IF NOT EXISTS governance_reserved_matters_status_idx ON governance_reserved_matters(status);
